{{ config(
            materialized='table',
                post_hook={
                    "sql": "drop table if exists tuco_kids_sales_consolidated_mid; create table tuco_kids_sales_consolidated_mid as with child_sku as ( select *, sum(child_quantity) OVER(PARTITION BY parent_sku) as total_parent_quantity, cast(child_quantity AS FLOAT) / SUM(child_quantity) OVER(PARTITION BY parent_sku) as child_ratio from ( select parent_sku, child_sku, child_product_name child_category, child_quantity, row_number() over (partition by parent_sku,child_sku order by 1 desc) as rw from public.tuco_kids_parent_child_sku_master ) where rw=1 ), child_count as( select parent_sku, count(child_sku) as child_sku_count from child_sku group by 1 ), child_sku_mapping as ( select c.*, p.mrp * child_ratio as child_mrp, round(CAST((child_quantity * child_mrp) AS FLOAT) / NULLIF(SUM(child_quantity * child_mrp) OVER(PARTITION BY parent_sku), 0),2) AS child_mrp_ratio from child_sku c left join (select * FROM( select sku, cast(mrp as double precision) as mrp, row_number() over (partition by sku order by 1 desc) as r from public.Easyecom_Tuco_Kids_product_master ) where r = 1 ) P on lower(p.sku::varchar) = lower(c.child_sku::varchar) ) select customer_id, shop_name, marketplace, channel, source, order_id, reference_code, tags, phone, name, email, shipping_last_update_date, sku, product_id, product_name, currency, city, state, order_status, order_date, order_time, s.quantity / NULLIF(COALESCE(c.child_sku_count, 1), 0) AS quantity, coalesce(s.quantity,0) * coalesce(p.child_mrp,1) as child_mrp, coalesce(s.gross_sales_before_tax,0) * coalesce(p.child_mrp_ratio,1) as gross_sales_before_tax, coalesce(s.discount,0) * coalesce(p.child_mrp_ratio,1) as discount, coalesce(s.tax,0) * coalesce(p.child_mrp_ratio,1) as tax, coalesce(s.shipping_price,0) * coalesce(p.child_mrp_ratio,1) as shipping_price, coalesce(s.selling_price,0) * coalesce(p.child_mrp_ratio,1) as selling_price, oms_order_status, shipping_status, final_shipping_status, saleorderitemcode, sales_order_item_id, awb, payment_gateway, payment_mode, courier, dispatch_date, delivered_date, delivered_status, return_flag, s.returned_quantity / NULLIF(COALESCE(c.child_sku_count, 1), 0) AS returned_quantity, coalesce(s.returned_sales,0) * coalesce(p.child_mrp_ratio,1) returned_sales, s.cancelled_quantity / NULLIF(COALESCE(c.child_sku_count, 1), 0) AS cancelled_quantity, new_customer_flag, acquisition_product, days_in_shipment, marketplace_acquisition_date, sku_code, product_name_final, product_category, product_sub_category, commonsku, warehouse, pincode, source_pincode, source_name, mapped_source_name, order_type, invoice_date, refund_date_final, refund_value, cancelled_at, size from public.tuco_kids_sales_consolidated_intermediate s left join child_sku_mapping p on p.parent_sku::varchar = replace(coalesce(s.commonsku, s.sku)::varchar,\'\"\',\'\') left join child_count c on trim(lower(replace(c.parent_sku,\'\"\',\'\'))) = trim(lower(replace(s.commonsku,\'\"\',\'\'))) ; DROP TABLE IF EXISTS public.GS_State_ISO; CREATE TABLE public.GS_State_ISO ( state VARCHAR(256), iso_code VARCHAR(10) ); DROP TABLE IF EXISTS public.Final_customerID; CREATE TABLE public.Final_customerID AS WITH new_phone_numbers AS ( SELECT phone, email, contact_num, 19700000000 + DENSE_RANK() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT RIGHT(REGEXP_REPLACE(phone, \'[^a-zA-Z0-9]+\', \'\'), 10) AS contact_num, email, phone FROM public.tuco_kids_sales_consolidated_intermediate WHERE phone IS NOT NULL ) a ), INT AS ( SELECT contact_num, email, COALESCE(maple_monk_id, id2) AS maple_monk_id FROM ( SELECT contact_num, email, maple_monk_id, 19800000000 + ROW_NUMBER() OVER (PARTITION BY maple_monk_id IS NULL ORDER BY email ASC) AS id2 FROM ( SELECT DISTINCT COALESCE(p.contact_num, RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10)) AS contact_num, e.email, COALESCE(p.maple_monk_id, pe.maple_monk_id) AS maple_monk_id FROM ( SELECT phone AS contact_num, email FROM public.tuco_kids_sales_consolidated_intermediate ) e LEFT JOIN new_phone_numbers p ON p.contact_num = RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10) LEFT JOIN ( SELECT * FROM ( SELECT * , ROW_NUMBER() OVER (PARTITION BY LOWER(email) ORDER BY 1) AS rn FROM new_phone_numbers ) sub WHERE rn = 1 ) pe ON LOWER(pe.email) = LOWER(e.email) ) b ) ) SELECT contact_num, email, maple_monk_id FROM INT WHERE COALESCE(contact_num, email) IS NOT NULL; DROP TABLE IF EXISTS public.tuco_kids_sales_consolidated; CREATE TABLE public.tuco_kids_sales_consolidated AS SELECT COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS customer_id_final, MIN(order_date) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS acquisition_date, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN order_date END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS first_complete_order_date, SUM(COALESCE(quantity, 0)) OVER (PARTITION BY reference_code) AS Order_Quantity, CASE WHEN (ABS(selling_price) > 10 AND (order_type IS NULL OR NOT (order_type IN (\'Test Order\',\'Photoshoot Order\',\'Stock Transfer Order\',\'Raw Material Order\',\'Influencer Order\',\'Return Prime Order\')))) THEN \'Gross Sale Orders\' ELSE \'Gross Orders\' END AS GROSS_ORDER_TYPE, CASE WHEN m.pincode LIKE \'1%\' OR m.pincode LIKE \'2%\' THEN \'North Region\' WHEN m.pincode LIKE \'3%\' OR m.pincode LIKE \'4%\' THEN \'West Region\' WHEN m.pincode LIKE \'5%\' OR m.pincode LIKE \'6%\' THEN \'South Region\' WHEN m.pincode LIKE \'7%\' OR m.pincode LIKE \'8%\' THEN \'East Region\' ELSE NULL END AS region, iso.iso_code AS state_iso_code, m.* FROM ( SELECT c.maple_monk_id AS maple_monk_id_phone, o.* FROM public.tuco_kids_sales_consolidated_intermediate o LEFT JOIN ( SELECT * FROM ( SELECT contact_num AS phone, maple_monk_id, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY maple_monk_id ASC) AS magic FROM public.Final_customerID ) WHERE magic = 1 ) c ON c.phone = RIGHT(REGEXP_REPLACE(o.phone, \'[^a-zA-Z0-9]+\', \'\'), 10) ) m LEFT JOIN ( SELECT DISTINCT maple_monk_id, email FROM public.Final_customerID WHERE contact_num IS NULL ) d ON d.email = m.email LEFT JOIN ( SELECT * FROM public.GS_State_ISO ) iso ON LOWER(REPLACE(iso.state, \' \', \'\')) = LOWER(REPLACE(m.state, \' \', \'\')); ALTER TABLE public.tuco_kids_sales_consolidated DROP COLUMN new_customer_flag; ALTER TABLE public.tuco_kids_sales_consolidated DROP COLUMN acquisition_product; ALTER TABLE public.tuco_kids_sales_consolidated ADD COLUMN new_customer_flag VARCHAR(256); ALTER TABLE public.tuco_kids_sales_consolidated ADD COLUMN new_customer_flag_month VARCHAR(256); ALTER TABLE public.tuco_kids_sales_consolidated ADD COLUMN acquisition_product VARCHAR(256); ALTER TABLE public.tuco_kids_sales_consolidated ADD COLUMN acquisition_channel VARCHAR(256); ALTER TABLE public.tuco_kids_sales_consolidated ADD COLUMN acquisition_marketplace VARCHAR(256); UPDATE public.tuco_kids_sales_consolidated SET new_customer_flag = B.flag FROM ( SELECT order_id, customer_id_final, order_date, CASE WHEN order_date = first_complete_order_date THEN \'New\' WHEN order_date < first_complete_order_date OR first_complete_order_date IS NULL THEN \'Yet to make completed order\' WHEN order_date > first_complete_order_date THEN \'Repeat\' END AS flag, ROW_NUMBER() OVER ( PARTITION BY order_id, customer_id_final ORDER BY order_date ) AS rw FROM public.tuco_kids_sales_consolidated ) AS B WHERE public.tuco_kids_sales_consolidated.order_id = B.order_id AND public.tuco_kids_sales_consolidated.customer_id_final = B.customer_id_final AND B.rw = 1; UPDATE public.tuco_kids_sales_consolidated SET new_customer_flag = CASE WHEN new_customer_flag IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' WHEN new_customer_flag IS NULL AND LOWER(order_status) IN (\'cancelled\') THEN \'Yet to make completed order\' ELSE new_customer_flag END WHERE new_customer_flag IS NULL; UPDATE public.tuco_kids_sales_consolidated SET new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, order_date, CASE WHEN DATE_TRUNC(\'month\', order_date) = DATE_TRUNC(\'month\', first_complete_order_date) THEN \'New\' WHEN DATE_TRUNC(\'month\', order_date) < DATE_TRUNC(\'month\', first_complete_order_date) OR acquisition_date IS NULL THEN \'Yet to make completed order\' WHEN DATE_TRUNC(\'month\', order_date) > DATE_TRUNC(\'month\', first_complete_order_date) THEN \'Repeat\' END AS flag, ROW_NUMBER() OVER (PARTITION BY order_id, customer_id_final ORDER BY order_date) AS rw FROM public.tuco_kids_sales_consolidated ) AS B WHERE public.tuco_kids_sales_consolidated.order_id = B.order_id AND public.tuco_kids_sales_consolidated.customer_id_final = B.customer_id_final AND B.rw = 1; UPDATE public.tuco_kids_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' ELSE new_customer_flag_month END WHERE new_customer_flag_month IS NULL; DROP TABLE IF EXISTS temp_source_1; CREATE TEMPORARY TABLE temp_source_1 AS SELECT customer_id_final, source AS channel, shop_name AS marketplace FROM ( SELECT * FROM( SELECT customer_id_final, order_date, source, shop_name, MIN(CASE WHEN LOWER(order_status) != \'cancelled\' THEN order_date END) OVER (PARTITION BY customer_id_final) AS firstOrderDate, ROW_NUMBER() OVER (PARTITION BY customer_id_final ORDER BY ORDER_TIME) AS rw FROM public.tuco_kids_sales_consolidated ) AS res WHERE rw = 1 ) WHERE order_date = firstOrderDate; UPDATE public.tuco_kids_sales_consolidated SET acquisition_channel = b.channel FROM temp_source_1 AS b WHERE public.tuco_kids_sales_consolidated.customer_id_final = b.customer_id_final; UPDATE public.tuco_kids_sales_consolidated SET acquisition_marketplace = b.marketplace FROM temp_source_1 AS b WHERE public.tuco_kids_sales_consolidated.customer_id_final = b.customer_id_final; DROP TABLE IF EXISTS temp_product_1; CREATE TEMPORARY TABLE temp_product_1 AS SELECT customer_id_final, product_name_final FROM ( SELECT customer_id_final, order_date, product_name_final, SELLING_PRICE, MIN(CASE WHEN LOWER(order_status) != \'cancelled\' THEN order_date END) OVER (PARTITION BY customer_id_final) AS firstOrderdate, ROW_NUMBER() OVER (PARTITION BY customer_id_final ORDER BY ORDER_TIME ASC, selling_price DESC) AS rw FROM public.tuco_kids_sales_consolidated ) res WHERE order_date = firstorderdate AND rw = 1; UPDATE public.tuco_kids_sales_consolidated SET acquisition_product = B.product_name_final FROM ( SELECT * FROM temp_product_1 ) AS B WHERE public.tuco_kids_sales_consolidated.customer_id_final = B.customer_id_final; UPDATE public.tuco_kids_sales_consolidated SET state = CASE WHEN UPPER(state) IN (\'AP\', \'ANDHRA PRADESH\', \'ANDHRAPRADESH\') THEN \'ANDHRA PRADESH\' WHEN UPPER(state) IN (\'AR\', \'ARUNACHAL PRADESH\') THEN \'ARUNACHAL PRADESH\' WHEN UPPER(state) IN (\'AS\', \'ASSAM\', \'ASSAM HINDUISM\') THEN \'ASSAM\' WHEN UPPER(state) IN (\'BR\', \'BIHAR\') THEN \'BIHAR\' WHEN UPPER(state) IN (\'CT\', \'CHHATTISGARH\', \'CHATTISGARH\', \'CHHATISGARH\') THEN \'CHHATTISGARH\' WHEN UPPER(state) IN (\'GA\', \'GOA\') THEN \'GOA\' WHEN UPPER(state) IN (\'GJ\', \'GUJARAT\', \'GUJRAT\') THEN \'GUJARAT\' WHEN UPPER(state) IN (\'HR\', \'HARYANA\') THEN \'HARYANA\' WHEN UPPER(state) IN (\'HP\', \'HIMACHAL PRADESH\', \'HIMANCHAL PRADESH\') THEN \'HIMACHAL PRADESH\' WHEN UPPER(state) IN (\'JH\', \'JHARKHAND\') THEN \'JHARKHAND\' WHEN UPPER(state) IN (\'KA\', \'KARNATAKA\', \'KARANATAKA\', \'KARNATKA\') THEN \'KARNATAKA\' WHEN UPPER(state) IN (\'KL\', \'KERALA\') THEN \'KERALA\' WHEN UPPER(state) IN (\'MP\', \'MADHYA PRADESH\', \'MADHYAPRADESH\', \'M. P\') THEN \'MADHYA PRADESH\' WHEN UPPER(state) IN (\'MH\', \'MAHARASHTRA\', \'MAHARASTRA\', \'MAHARASHATRA\', \'MAHASHTRA\', \'MUMBAI THANA\') THEN \'MAHARASHTRA\' WHEN UPPER(state) IN (\'MN\', \'MANIPUR\') THEN \'MANIPUR\' WHEN UPPER(state) IN (\'ML\', \'MEGHALAYA\', \'MEGALAYA\') THEN \'MEGHALAYA\' WHEN UPPER(state) IN (\'MZ\', \'MIZORAM\') THEN \'MIZORAM\' WHEN UPPER(state) IN (\'NL\', \'NAGALAND\') THEN \'NAGALAND\' WHEN UPPER(state) IN (\'OR\', \'ODISHA\', \'ORISSA\') THEN \'ODISHA\' WHEN UPPER(state) IN (\'PB\', \'PUNJAB\') THEN \'PUNJAB\' WHEN UPPER(state) IN (\'RJ\', \'RAJASTHAN\') THEN \'RAJASTHAN\' WHEN UPPER(state) IN (\'SK\', \'SIKKIM\') THEN \'SIKKIM\' WHEN UPPER(state) IN (\'TN\', \'TAMIL NADU\', \'TAMILNADU\') THEN \'TAMIL NADU\' WHEN UPPER(state) IN (\'TS\', \'TL\', \'TELANGANA\') THEN \'TELANGANA\' WHEN UPPER(state) IN (\'TR\', \'TRIPURA\') THEN \'TRIPURA\' WHEN UPPER(state) IN (\'UP\', \'UTTAR PRADESH\', \'UTTER PRADESH\') THEN \'UTTAR PRADESH\' WHEN UPPER(state) IN (\'UT\', \'UK\', \'UTTARAKHAND\', \'UTTRAKHAND\') THEN \'UTTARAKHAND\' WHEN UPPER(state) IN (\'WB\', \'WEST BENGAL\', \'WEST BANGAL\', \'WB(KOLKATA & HOWRAH AREA)\') THEN \'WEST BENGAL\' WHEN UPPER(state) IN (\'AN\', \'ANDAMAN AND NICOBAR ISLANDS\', \'ANDAMAN & NICOBAR ISLANDS\') THEN \'ANDAMAN AND NICOBAR ISLANDS\' WHEN UPPER(state) IN (\'CH\', \'CHANDIGARH\') THEN \'CHANDIGARH\' WHEN UPPER(state) IN (\'DN\', \'DADRA AND NAGAR HAVELI\', \'DADRA & NAGAR HAVELI\', \'DD\', \'DAMAN AND DIU\', \'DAMAN & DIU\', \'DADRA & NAGAR HAVELI AND DAMAN & DIU\', \'DADRA AND NAGAR HAVELI AND DAMAN AND DIU\', \'DADRA AND NAGAR HAV.\') THEN \'DADRA AND NAGAR HAVELI AND DAMAN AND DIU\' WHEN UPPER(state) IN (\'LD\', \'LAKSHADWEEP\') THEN \'LAKSHADWEEP\' WHEN UPPER(state) IN (\'DL\', \'DELHI\', \'NEW DELHI\', \'NCR\') THEN \'DELHI\' WHEN UPPER(state) IN (\'PY\', \'PUDUCHERRY\', \'PONDICHERRY\') THEN \'PUDUCHERRY\' WHEN UPPER(state) IN (\'JK\', \'JAMMU AND KASHMIR\', \'JAMMU & KASHMIR\') THEN \'JAMMU AND KASHMIR\' WHEN UPPER(state) = \'LADAKH\' THEN \'LADAKH\' WHEN UPPER(state) IN (\'AUCKLAND\', \'UNITED KINGDOM (+44)\', \'NON-US\', \'ZEELAND\', \'SINGAPORE\', \'BARCELONA\') THEN NULL WHEN UPPER(state) IN (\'INDIA\', \'1493\', \'BJP.TEAM211@GMAIL.COM\') THEN NULL WHEN UPPER(state) IN (\'NOT SPECIFIED\', \'\') THEN NULL ELSE state END; DROP TABLE IF EXISTS public.tuco_kids_sales_consolidated_final; CREATE TABLE public.tuco_kids_sales_consolidated_final AS SELECT customer_id_final, acquisition_date, first_complete_order_date, Order_Quantity, tags, GROSS_ORDER_TYPE, region, maple_monk_id_phone, customer_id, SHOP_NAME, marketplace, CHANNEL, SOURCE, ORDER_ID, reference_code, PHONE, NAME, EMAIL, SHIPPING_LAST_UPDATE_DATE, SKU, PRODUCT_ID, PRODUCT_NAME, CURRENCY, CITY, State, ORDER_STATUS, Order_Date, Order_Time, QUANTITY, GROSS_SALES_BEFORE_TAX, DISCOUNT, TAX, SHIPPING_PRICE, SELLING_PRICE, OMS_order_status, SHIPPING_STATUS, FINAL_SHIPPING_STATUS, SALEORDERITEMCODE, SALES_ORDER_ITEM_ID, AWB, PAYMENT_GATEWAY, payment_mode, COURIER, DISPATCH_DATE, DELIVERED_DATE, DELIVERED_STATUS, RETURN_FLAG, returned_quantity, returned_sales, cancelled_quantity, Days_in_Shipment, MARKETPLACE_ACQUISITION_DATE, SKU_CODE, PRODUCT_NAME_FINAL, PRODUCT_CATEGORY, PRODUCT_SUB_CATEGORY, commonsku, WAREHOUSE, pincode, source_pincode, Source_name, Mapped_Source_Name, Order_Type, invoice_date, refund_date_final, refund_value, new_customer_flag, new_customer_flag_month, acquisition_product, acquisition_channel, acquisition_marketplace, NULL::NUMERIC AS shopify_refund_value, NULL::NUMERIC AS return_tax, cancelled_at, state_iso_code FROM public.tuco_kids_sales_consolidated UNION ALL SELECT NULL::BIGINT AS customer_id_final, NULL::DATE AS acquisition_date, NULL::DATE AS first_complete_order_date, NULL::NUMERIC AS Order_Quantity, NULL::VARCHAR(256) AS tags, CASE WHEN (ABS(refund_value) > 10 AND (order_type IS NULL OR NOT (order_type IN (\'Photoshoot Order\',\'Stock Transfer Order\',\'Raw Material Order\',\'Influencer Order\')))) THEN \'Gross Sale Orders\' ELSE \'Gross Orders\' END AS GROSS_ORDER_TYPE, region, maple_monk_id_phone, customer_id, SHOP_NAME, marketplace, CHANNEL, SOURCE, NULL::VARCHAR(256) AS ORDER_ID, NULL::VARCHAR(256) AS reference_code, NULL::VARCHAR(256) AS PHONE, NULL::VARCHAR(256) AS NAME, NULL::VARCHAR(256) AS EMAIL, NULL::TIMESTAMP AS SHIPPING_LAST_UPDATE_DATE, NULL::VARCHAR(256) AS SKU, NULL::VARCHAR(256) AS PRODUCT_ID, NULL::VARCHAR(256) AS PRODUCT_NAME, NULL::VARCHAR(256) AS CURRENCY, CITY, State, NULL::VARCHAR(256) AS ORDER_STATUS, refund_date_final AS Order_Date, NULL::TIMESTAMP AS Order_Time, NULL::NUMERIC AS QUANTITY, NULL::NUMERIC AS GROSS_SALES_BEFORE_TAX, NULL::NUMERIC AS DISCOUNT, NULL::NUMERIC AS TAX, NULL::NUMERIC AS SHIPPING_PRICE, NULL::NUMERIC AS SELLING_PRICE, NULL::VARCHAR(256) AS OMS_order_status, NULL::VARCHAR(256) AS SHIPPING_STATUS, NULL::VARCHAR(256) AS FINAL_SHIPPING_STATUS, NULL::VARCHAR(256) AS SALEORDERITEMCODE, NULL::VARCHAR(256) AS SALES_ORDER_ITEM_ID, NULL::VARCHAR(256) AS AWB, NULL::VARCHAR(256) AS PAYMENT_GATEWAY, NULL::VARCHAR(256) AS payment_mode, NULL::VARCHAR(256) AS COURIER, NULL::DATE AS DISPATCH_DATE, NULL::DATE AS DELIVERED_DATE, NULL::BIGINT AS DELIVERED_STATUS, NULL::BIGINT AS RETURN_FLAG, NULL::NUMERIC AS returned_quantity, NULL::NUMERIC AS returned_sales, NULL::BIGINT AS cancelled_quantity, NULL::BIGINT AS Days_in_Shipment, NULL::DATE AS MARKETPLACE_ACQUISITION_DATE, NULL::VARCHAR(256) AS SKU_CODE, NULL::VARCHAR(256) AS PRODUCT_NAME_FINAL, NULL::VARCHAR(256) AS PRODUCT_CATEGORY, NULL::VARCHAR(256) AS PRODUCT_SUB_CATEGORY, NULL::VARCHAR(256) AS commonsku, NULL::VARCHAR(256) AS WAREHOUSE, NULL::VARCHAR(20) AS pincode, NULL::VARCHAR(20) AS source_pincode, NULL::VARCHAR(256) AS Source_name, NULL::VARCHAR(256) AS Mapped_Source_Name, Order_Type, NULL::DATE AS invoice_date, refund_date_final, refund_value, NULL::VARCHAR(256) AS new_customer_flag, NULL::VARCHAR(256) AS new_customer_flag_month, NULL::VARCHAR(256) AS acquisition_product, NULL::VARCHAR(256) AS acquisition_channel, NULL::VARCHAR(256) AS acquisition_marketplace, refund_value AS shopify_refund_value, tax AS return_tax, NULL::TIMESTAMP AS cancelled_at, state_iso_code FROM public.tuco_kids_sales_consolidated WHERE (LOWER(marketplace) LIKE \'%shopify%\' OR LOWER(marketplace) LIKE \'%website%\') AND COALESCE(refund_value, 0) > 0;",
